// A person's own shape drawn by the open-bot-avatar engine itself (#4159;
// MIT, see NOTICE). A catalog shape has a baked still (ShapeEngineStillData);
// a person's own drawing or a pasted definition has none, so the desktop
// infers its volume at run time (`runtimeStill(lookDefinition(...))` in
// src/components/shape-avatar.ts). The phone runs that very code in
// JavaScriptCore: Resources/shape-engine.js is the desktop's function bundled
// with the unmodified engine (generated by ios-mascot-export.test.ts from
// ios/parity/shape-engine.entry.ts), so both draw the same frames, and a
// definition the engine refuses falls back to the bot's shape as on the
// desktop. The inference runs once per definition and depth, off the main
// thread in a view; the still is kept.
import Foundation
#if canImport(JavaScriptCore)
import JavaScriptCore
#endif

public enum ShapeEngineBake {
    private struct Key: Hashable {
        var shape: MascotShape
        var flat: Bool
        var avatarDef: MascotAvatarDef
    }

    private static let lock = NSLock()
    private static var cache: [Key: ShapeEngineStill] = [:]
    /// Definitions the engine could not draw here: asked once, never again.
    private static var failed: Set<Key> = []
    #if canImport(JavaScriptCore)
    private static var runtime: JSValue?
    private static var loaded = false
    #endif

    /// The still the desktop draws for a look's own shape (`runtimeStill`),
    /// in volume or flat (depth 0, the Outline skin); nil only when the engine
    /// cannot run here. The first call for a definition runs the engine and
    /// can take a moment: a view asks `isReady` and bakes off the main thread.
    public static func still(_ shape: MascotShape, avatarDef: MascotAvatarDef, flat: Bool = false) -> ShapeEngineStill? {
        let key = Key(shape: shape, flat: flat, avatarDef: avatarDef)
        lock.lock()
        defer { lock.unlock() }
        if let hit = cache[key] { return hit }
        if failed.contains(key) { return nil }
        let encoder = JSONEncoder()
        encoder.outputFormatting = .sortedKeys
        guard let data = try? encoder.encode(avatarDef), let json = String(data: data, encoding: .utf8),
              let file = stillFile(shape.rawValue, json, flat), let still = ShapeEngineStill.read(file) else {
            failed.insert(key)
            return nil
        }
        cache[key] = still
        return still
    }

    /// True once `still` answers at once for this definition (baked, or known not to draw).
    public static func isReady(_ shape: MascotShape, avatarDef: MascotAvatarDef, flat: Bool = false) -> Bool {
        let key = Key(shape: shape, flat: flat, avatarDef: avatarDef)
        lock.lock()
        defer { lock.unlock() }
        return cache[key] != nil || failed.contains(key)
    }

    /// `lookStill` of shape-engine.js: the still file (`StillFile` JSON). Called under the lock.
    static func stillFile(_ shape: String, _ avatarDef: String, _ flat: Bool) -> String? {
        #if canImport(JavaScriptCore)
        if !loaded {
            loaded = true
            guard let url = Bundle.module.url(forResource: "shape-engine", withExtension: "js"),
                  let source = try? String(contentsOf: url, encoding: .utf8),
                  let context = JSContext() else { return nil }
            context.evaluateScript(source, withSourceURL: url)
            if context.exception == nil, let function = context.objectForKeyedSubscript("lookStill"), !function.isUndefined {
                runtime = function
            }
        }
        guard let runtime, let context = runtime.context else { return nil }
        let result = runtime.call(withArguments: [shape, avatarDef, flat])
        if context.exception != nil {
            context.exception = nil
            return nil
        }
        guard let result, result.isString else { return nil }
        return result.toString()
        #else
        return nil
        #endif
    }
}

public extension ShapeEngineStill {
    /// The catalog shape whose baked still a look draws (`bakedShapeFor`):
    /// its own shape, a saved object preset's, or none for a person's own shape.
    static func bakedShape(_ shape: MascotShape, avatarDef: MascotAvatarDef?) -> MascotShape? {
        guard let avatarDef else { return shape }
        guard case let .own(def) = avatarDef, let id = def.id, let preset = MascotShape.stored(id), ShapeAvatarPresets.isObjectShape(preset) else { return nil }
        return preset
    }

    /// The still a look draws (`ShapeMascot.tsx`): the baked still, else the
    /// engine's still of the person's own shape (`runtimeStill(lookDefinition(...))`),
    /// in volume or flat (the Outline skin).
    static func of(_ shape: MascotShape, avatarDef: MascotAvatarDef?, flat: Bool = false) -> ShapeEngineStill? {
        if let baked = bakedShape(shape, avatarDef: avatarDef) { return of(baked, flat: flat) }
        guard let avatarDef else { return nil }
        return ShapeEngineBake.still(shape, avatarDef: avatarDef, flat: flat) ?? of(shape, flat: flat)
    }
}
